-- Cabin Crew · Aulas de texto dos cursos Head Hunter (18) e Conduta Profissional (25)
-- Gerado por scripts/aulas-hh-conduta.py. Pode rodar mais de uma vez (atualiza, não duplica).
-- As aulas entram como RASCUNHO. Revise em Admin → Crew Select e publique, ou rode 0027_publicar_aulas_importadas.sql.
-- Aulas que você já publicou continuam publicadas (o publicado não é alterado na atualização).

insert into aulas (modulo_id, ordem, titulo, resumo, conteudo, duracao_min, origem, tipo, publicado)
select m.id, v.ordem, v.titulo, v.resumo, v.conteudo, v.dur, v.origem, 'texto', false
from (values
  (1, 11, 'Como Funcionam as Seleções das Companhias Aéreas', 'Entenda a estrutura completa dos processos seletivos das companhias aéreas, do edital à contratação, e o que realmente diferencia candidatos aprovados de eliminados em cada etapa.', '<h2><span>Como Funcionam as Seleções das Companhias Aéreas</span></h2><p>Entenda a estrutura completa dos processos seletivos das companhias aéreas — do edital à contratação — e o que realmente diferencia candidatos aprovados de eliminados em cada etapa.</p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-funil.png" alt="Etapas do funil seletivo" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-elimina.png" alt="Motivos de eliminação" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-eixos.png" alt="Seis eixos comportamentais" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-perfis.png" alt="Perfil aprovado x reprovado" loading="lazy" /></p><blockquote><p>Recrutadores experientes afirmam que decidem sobre muitos candidatos nos primeiros 5 minutos de contato — antes de qualquer resposta formal. Cuide de cada detalhe desde a chegada ao local de seleção.</p></blockquote>', 12, 'horsky-hh-72ccb73e-33d7-4645-b820-1b7abad47a15'),
  (1, 12, 'Mentalidade Profissional para Aviação', 'Antes de qualquer técnica, existe uma forma de pensar. A mentalidade certa é o que separa candidatos que passam da seleção daqueles que sabem as respostas mas não convencem ninguém.', '<p>Antes de qualquer técnica, existe uma forma de pensar. A mentalidade certa é o que separa candidatos que passam da seleção daqueles que sabem as respostas mas não convencem ninguém.</p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-pilares.png" alt="Quatro pilares" loading="lazy" /></p><blockquote><p>Mentalidade não é o que você diz que tem — é o que aparece quando as coisas ficam difíceis. Recrutadores criam situações de pressão justamente para ver qual mentalidade emerge.</p></blockquote><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-postura.png" alt="Postura e imagem" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-comunicacao.png" alt="Comunicação eficaz" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-grupo.png" alt="Comportamento em grupo" loading="lazy" /></p><blockquote><p>Recrutadores frequentemente decidem candidatos com base no que observam nos momentos não estruturados. A seleção começa antes de você entrar na sala.</p></blockquote><h3>Perguntas para reflexão</h3><ul><li>Se alguém te observasse sem você saber, diria que você tem postura de comissário?</li><li>Em situações de pressão, sua comunicação melhora ou piora? Por quê?</li><li>Em um grupo, você tende a falar mais ou menos do que deveria?</li><li>Qual dos quatro pilares de mentalidade você precisa desenvolver mais?</li></ul>', 14, 'horsky-hh-05e5f6d8-4811-4102-9b7f-a28d340c095d'),
  (6, 21, 'Gramática Aplicada à Aviação', 'Domine os pontos gramaticais que mais aparecem nas provas de seleção aérea e elimine erros desnecessários que custam pontos evitáveis.', '<p>Dominar os pontos gramaticais que mais aparecem nas provas de seleção aérea elimina erros desnecessários e aumenta a pontuação sem exigir estudo enciclopédico.</p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-gramatica.png" alt="Pontos gramaticais mais cobrados" loading="lazy" /></p><h3>Vocabulário técnico da aviação</h3><p>Dominar o vocabulário correto demonstra preparo e familiaridade com a profissão tanto nas provas escritas quanto nas entrevistas.</p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-vocab-pt.png" alt="Vocabulário técnico da aviação" loading="lazy" /></p><blockquote><p>Muitas questões de português em seleções aéreas usam textos sobre aviação como base. Conhecer o vocabulário técnico acelera a leitura e evita erros de interpretação por desconhecimento do tema.</p></blockquote>', 16, 'horsky-hh-9733bb24-9b6e-4ede-81f2-b38ee0803e3e'),
  (6, 22, 'Interpretação de Texto e Comunicação Formal', 'Aprenda a interpretar textos técnicos aeronáuticos com precisão e a usar a linguagem formal adequada em entrevistas, relatos e comunicação com passageiros.', '<p>Textos instrucionais e regulatórios são base frequente das provas de português em seleções aéreas. Interpretar com precisão — sem adicionar nem subtrair informações — é exatamente o que as questões avaliam.</p><h3>O que realmente avalia</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-leitura-avalia.png" alt="O que a prova de interpretação realmente avalia" loading="lazy" /></p><h3>Texto base de exemplo</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-texto-base.png" alt="Texto base e perguntas de interpretação" loading="lazy" /></p><h3>Comunicação formal e verbal com passageiros</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-comunic-formal.png" alt="Comunicação escrita e verbal formal" loading="lazy" /></p><blockquote><p>A forma como você fala revela o quanto você se preparou. Recrutadores percebem imediatamente quem praticou a comunicação formal e quem apenas decorou respostas.</p></blockquote>', 13, 'horsky-hh-e64413dd-e538-44f9-a8f9-10da3898c259'),
  (6, 31, 'Vocabulário e Frases Padrão de Cabine', 'Domine o vocabulário aeronáutico essencial e as frases padrão usadas em cada fase do voo, do embarque às emergências.', '<p>O inglês aeronáutico tem um repertório específico de frases que todo comissário precisa dominar — organizadas pela sequência real do voo, do embarque ao pouso.</p><h3>Vocabulário técnico essencial</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-safety.png" alt="Vocabulário de segurança" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-service.png" alt="Vocabulário de serviço de bordo" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-aircraft.png" alt="Vocabulário da aeronave" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-operation.png" alt="Vocabulário de operação" loading="lazy" /></p><h3>Frases padrão — embarque</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-boarding.png" alt="Frases padrão de embarque" loading="lazy" /></p><h3>Frases padrão — demonstração de segurança</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-safety-demo.png" alt="Frases da demonstração de segurança" loading="lazy" /></p><h3>Frases padrão — serviço de bordo</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-bordo.png" alt="Frases de serviço de bordo" loading="lazy" /></p><h3>Frases padrão — turbulência</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-turbulencia.png" alt="Frases padrão de turbulência" loading="lazy" /></p><h3>Frases padrão — pouso</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-pouso.png" alt="Frases padrão de pouso" loading="lazy" /></p><h3>Frases padrão — emergências</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-emergencias.png" alt="Frases padrão de emergências" loading="lazy" /></p><blockquote><p>Em emergências, a clareza e firmeza da voz são tão importantes quanto as palavras. Pratique os comandos de evacuação em voz alta — o tom transmite autoridade e controla o pânico dos passageiros.</p></blockquote>', 18, 'horsky-hh-13bd7dd9-16c8-486c-bcb8-6b01e3cc8557'),
  (6, 32, 'Diálogos Reais e Leitura Técnica em Inglês', 'Pratique diálogos completos com passageiros em situações reais e aprenda a interpretar manuais e documentos técnicos em inglês.', '<p>A comunicação eficaz com passageiros exige validação da emoção, linguagem formal e compromisso com a solução. Manuais e documentos operacionais são redigidos em inglês formal com vocabulário que precisa ser reconhecido de imediato.</p><h3>Diálogos reais com passageiros</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-dialogos.png" alt="Diálogos reais com passageiros" loading="lazy" /></p><h3>Estratégia de leitura técnica em inglês</h3><ul><li><strong>Leia o parágrafo completo antes de responder:</strong> textos técnicos têm estrutura lógica — a conclusão frequentemente está no último período.</li><li><strong>Identifique verbos de obrigação:</strong> <em>must</em> e <em>shall</em> indicam procedimento obrigatório. <em>Should</em> indica recomendação. <em>May</em> indica permissão.</li><li><strong>Atenção a negações compostas:</strong> <em>do not inflate inside the aircraft</em> muda completamente o sentido da instrução.</li></ul><h3>Excerto de manual — glossário</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-en-manual.png" alt="Excerto de manual e glossário" loading="lazy" /></p><h3>Gramática aplicada a anúncios de PA</h3><p>Anúncios formais de cabine usam estruturas específicas que diferem do inglês cotidiano:</p><ul><li><strong>Correto:</strong> <em>We will shortly begin our descent.</em></li><li><strong>Informal demais para PA:</strong> <em>We are going to start going down soon.</em></li><li><strong>Correto:</strong> <em>Ladies and gentlemen, we will shortly be commencing our descent.</em></li></ul><blockquote><p>Candidatos que dominam o inglês aeronáutico específico — não apenas o inglês geral — demonstram preparo real e se destacam imediatamente na fase de testes e entrevistas.</p></blockquote>', 15, 'horsky-hh-95d53d19-d4a2-4f8b-9286-9eb507f86518'),
  (6, 41, 'Padrões e Sequências', 'Aprenda a identificar a lei de formação de sequências numéricas e figurais e resolva questões com rapidez e precisão.', '<p>Sequências numéricas e figurais estão entre os tipos de questão mais frequentes em provas de seleção aérea. A chave é identificar a lei de formação antes de olhar as alternativas — que são construídas para induzir ao erro quem não encontrou o padrão.</p><h3>Tipos de questões de raciocínio lógico</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-rl-categorias.png" alt="Categorias de raciocínio lógico" loading="lazy" /></p><h3>Tipos de sequência numérica</h3><ul><li><strong>Progressão aritmética:</strong> diferença constante entre termos. Ex: 3, 6, 9, 12 — razão +3.</li><li><strong>Progressão geométrica:</strong> razão multiplicativa constante. Ex: 3, 6, 12, 24 — razão ×2.</li><li><strong>Diferenças crescentes:</strong> os intervalos entre termos aumentam em progressão aritmética. Ex: 2, 5, 10, 17, 26 — diferenças +3, +5, +7, +9.</li><li><strong>Sequências alternadas:</strong> dois padrões entrelaçados nos termos ímpares e pares. Ex: 1, 10, 3, 8, 5, 6, 7 — ímpares +2, pares −2.</li><li><strong>Quadrados perfeitos:</strong> 1, 4, 9, 16, 25, 36 — reconhecimento imediato economiza tempo.</li><li><strong>Fibonacci e variações:</strong> cada termo é a soma dos anteriores. Ex: 0, 1, 1, 2, 3, 5, 8, 13.</li></ul><h3>Sequências de letras</h3><p>Use as posições no alfabeto como números. Ex: B(2), E(5), H(8), K(11), N(14), Q(17) — salto +3 a cada letra.</p><ul><li>A=1, B=2, C=3... Z=26.</li><li>Calcule as diferenças entre posições exatamente como em sequências numéricas.</li><li>Ex: A, C, F, J, O — saltos: +2, +3, +4, +5 → próxima +6 → U(21).</li></ul><h3>Estratégia de resolução</h3><ul><li>Calcule as diferenças entre todos os termos consecutivos antes de procurar o padrão.</li><li>Se as diferenças não forem constantes, calcule as diferenças das diferenças.</li><li>Nunca olhe as alternativas antes de identificar a lei.</li><li>Se travou, pule e volte — questões simples em branco por falta de tempo prejudicam mais do que questões difíceis erradas.</li></ul><h3>Sequências figurais</h3><p>Analise um atributo por vez: forma, tamanho, preenchimento e posição. Quem tenta ver tudo ao mesmo tempo trava. Uma passada para forma, outra para tamanho — em dois ciclos de análise, o padrão emerge.</p><ul><li>Observe se as figuras giram, espelham ou se alternam.</li><li>Verifique quantidade de lados, tamanho relativo e padrão de preenchimento separadamente.</li><li>Em matrizes 3×3, compare linha por linha e depois coluna por coluna.</li></ul><blockquote><p>Questões ficam mais complexas no final da prova. Não gaste tempo excessivo nas primeiras — reserve energia cognitiva para os itens mais pesados.</p></blockquote>', 15, 'horsky-hh-ba397377-cbe6-4c2a-9359-070086ffa0ce'),
  (6, 42, 'Proposições, Analogias e Silogismos', 'Domine lógica proposicional, analogias e silogismos — os três pilares das questões de raciocínio formal em seleções aéreas.', '<p>Lógica proposicional, analogias e silogismos compõem a base das questões de raciocínio formal nas seleções aéreas. Dominar as regras elimina a dependência da intuição, que frequentemente falha nesse tipo de questão.</p><h3>Proposições e conectivos lógicos</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-rl-conectivos.png" alt="Conectivos lógicos e tabela verdade" loading="lazy" /></p><h3>Analogias — tipos de relação</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-rl-analogias.png" alt="Tipos de analogias" loading="lazy" /></p><h3>Silogismos — conclusões válidas a partir de premissas</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-rl-silogismos.png" alt="Silogismos válidos e inválidos" loading="lazy" /></p><p>Use a <strong>contrapositiva</strong>: se A→B, então ¬B→¬A. Se toda aprovada passou no inglês, quem não passou no inglês não foi aprovada.</p><blockquote><p>Conclusões que <em>parecem razoáveis</em> são a principal armadilha dos silogismos. Se a informação não está nas premissas, não pode estar na conclusão.</p></blockquote>', 14, 'horsky-hh-f56ef31c-e539-49f2-b011-7754559476ca'),
  (6, 51, 'Como Empresas Aéreas Avaliam Seu Perfil Cognitivo', 'Entenda as cinco dimensões cognitivas que as companhias aéreas avaliam e como recrutadores interpretam os resultados além da pontuação bruta.', '<p>Recrutadores não procuram o candidato mais inteligente — procuram o perfil cognitivo mais adequado ao ambiente da aviação: pressão, imprevisibilidade e responsabilidade simultânea com múltiplos passageiros.</p><h3>As cinco dimensões avaliadas</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-dimensoes.png" alt="As cinco dimensões cognitivas avaliadas" loading="lazy" /></p><h3>Mapa de perfil cognitivo</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-radar-ideal.png" alt="Perfil ideal do comissário" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-radar-logica.png" alt="Perfil alto em lógica baixo em atenção" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-radar-veloz.png" alt="Perfil veloz mas impreciso" loading="lazy" /></p><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-radar-ie.png" alt="Perfil alto em IE baixo em lógica" loading="lazy" /></p><h3>Ajuste seu perfil</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-perfil-ajuste.png" alt="Simulador de ajuste de perfil cognitivo" loading="lazy" /></p><h3>O que recrutadores comparam</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-recrutadores-comparam.png" alt="O que recrutadores comparam" loading="lazy" /></p><h3>Como preparar cada dimensão</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-dicas-prep.png" alt="Dicas de preparação cognitiva" loading="lazy" /></p><h3>Mitos sobre os testes cognitivos</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-mitos.png" alt="Mitos sobre testes cognitivos" loading="lazy" /></p><blockquote><p>Cognição pode ser treinada — especialmente as dimensões que mais pesam na avaliação aérea. Com preparação consistente, o perfil pode mudar significativamente em 4 a 8 semanas.</p></blockquote>', 13, 'horsky-hh-3b7120d2-38f5-41e9-b3dc-78bcaf003c28'),
  (6, 52, 'Como Funcionam os Testes SHL', 'Visão completa das cinco baterias SHL usadas em seleções aéreas — formatos, o que medem, como são pontuados e estratégias específicas para cada uma.', '<p>A SHL é a maior fornecedora global de testes psicométricos para seleção corporativa, usada por LATAM, Azul, GOL e companhias internacionais. Conhecer o formato antes da seleção elimina o efeito de novidade — que consome tempo cognitivo precioso nas primeiras questões.</p><h3>O que é a SHL e por que as aéreas usam</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-cog-shl-formato.png" alt="Formato dos testes SHL" loading="lazy" /></p><h3>As cinco baterias para comissários</h3><h4>Verbal Reasoning (VR) — 19 min, 30 questões</h4><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-verbal-explicacao.png" alt="Raciocínio Verbal" loading="lazy" /></p><h4>Numerical Reasoning (NR) — 25 min, 18 questões</h4><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-numerico-explicacao.png" alt="Raciocínio Numérico" loading="lazy" /></p><h4>Inductive Reasoning (IR) — 25 min, 24 questões</h4><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-indutivo-explicacao.png" alt="Raciocínio Indutivo" loading="lazy" /></p><h4>Deductive Reasoning (DR) — 20 min, 20 questões</h4><p>Silogismos e lógica formal. Descarte alternativas erradas em vez de confirmar a certa. Use a contrapositiva. Nunca adicione informação além das premissas.</p><h4>Situational Judgement Test (SJT) — 30 min, 26 cenários</h4><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-sjt-explicacao.png" alt="Situational Judgement Test" loading="lazy" /></p><h3>Sistema de pontuação — percentil e stenine</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-faixas-desempenho-shl.png" alt="Faixas de desempenho SHL" loading="lazy" /></p><h3>O que acontece durante a aplicação</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-como-funciona-teste-shl.png" alt="Como funciona o teste SHL" loading="lazy" /></p><h3>Estratégias específicas por bateria</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-dicas-por-bateria.png" alt="Dicas por bateria" loading="lazy" /></p>', 17, 'horsky-hh-680306e1-33e0-466a-b7a9-3b077c0f7eac'),
  (6, 61, 'Liderança, Pressão e Tomada de Decisão', 'Entenda como liderança situacional, gestão de pressão e tomada de decisão estruturada são avaliadas em seleções aéreas e o que diferencia perfis aprovados.', '<p>As companhias aéreas avaliam comportamento em quatro eixos interdependentes. Recrutadores observam o equilíbrio entre as dimensões — não a intensidade de uma única delas.</p><h3>Liderança situacional</h3><h3><br>Gestão de pressão</h3><blockquote><p>Profissionalismo não significa suprimir emoções — significa canalizá-las no contexto certo. Manter a qualidade do serviço durante um voo difícil enquanto trata a questão no canal adequado é exatamente o que uma empresa de alto padrão espera.</p></blockquote><h3>Tomada de decisão</h3><p>A bordo, decisões precisam ser tomadas com informação parcial, sob pressão de tempo e com consequências reais. O que a companhia avalia é se você decidiu de forma estruturada e dentro dos protocolos.</p><ul><li><p><strong>Recrutadores valorizam:</strong> priorizar segurança automaticamente sem hesitar; decidir dentro do protocolo mesmo sob pressão social; verbalizar o raciocínio ao tomar decisão em equipe; reavaliar se surgir informação nova sem ego.</p></li><li><p><strong>Sinais de alerta:</strong> demorar a decidir em situações que pedem agilidade; decidir por intuição sem checar o protocolo; não comunicar o raciocínio para a equipe; manter a decisão errada por medo de errar publicamente.</p></li></ul><h3>A interação entre as dimensões</h3><p>Uma liderança sem controle emocional vira autoritarismo. Trabalho em equipe sem iniciativa vira omissão. Tomada de decisão sem humildade vira impulsividade. Os recrutadores avaliam o equilíbrio — não a intensidade de uma única dimensão.</p>', 16, 'horsky-hh-0c3ac4e8-8b5c-4be2-97d0-23747ca7a9a0'),
  (6, 62, 'Trabalho em Equipe e Cenários Comportamentais', 'Aprenda como o trabalho em equipe é avaliado na aviação e pratique respostas a cenários comportamentais reais usados em seleções.', '<p>A tripulação de cabine é uma equipe de alto desempenho que se forma às vezes horas antes do voo. Recrutadores avaliam como você entra em sistemas de trabalho que não escolheu e contribui sem atritar.</p><h3>Trabalho em equipe na aviação</h3><p><img src="https://horsky.com.br/upload/image/course-headhunter/img-perfil-trabalho-equipe.png" alt="Trabalho em equipe" loading="lazy" /></p><h3>Cenário 1 — passageiro insatisfeito com assento</h3><p><strong>Situação:</strong> durante o embarque, você percebe que um passageiro idoso está com dificuldade de encontrar seu assento e os demais tripulantes estão ocupados com outras tarefas. Nenhum superior te orientou sobre isso.</p><ul><li><strong>Resposta adequada:</strong> abordar o passageiro com gentileza, verificar o cartão de embarque e acompanhá-lo ao assento. Liderança situacional significa agir dentro da própria alçada sem precisar de comando.</li><li><strong>Respostas inadequadas:</strong> aguardar o chefe de cabine; pedir a outro passageiro que ajude; informar o comandante antes de agir.</li></ul><h3>Cenário 2 — passageiro agressivo durante o serviço</h3><p><strong>Situação:</strong> um passageiro levanta o tom de voz com você durante o serviço, reclamando que sua refeição chegou fria. Outros passageiros ao redor observam.</p><ul><li><strong>Resposta adequada:</strong> manter o tom calmo, validar o desconforto do passageiro e informar o que pode ser feito concretamente. Você controla o que pode — a resposta — não o que não pode — o comportamento do outro.</li><li><strong>Respostas inadequadas:</strong> responder em tom firme que não tolera ser tratado dessa forma; pedir desculpas repetidamente prometendo algo sem saber se conseguirá cumprir.</li></ul><h3>Cenário 3 — cintos no pouso</h3><p><strong>Situação:</strong> durante a descida final, um passageiro está com o encosto reclinado e a bandeja aberta. O aviso de preparo para pouso foi dado há 2 minutos. Você já orientou o passageiro uma vez.</p><ul><li><strong>Resposta adequada:</strong> reclinar o encosto e fechar a bandeja você mesmo, informando ao passageiro que é obrigatório. Segurança tem prioridade sobre conforto — e o protocolo de pouso é inegociável.</li><li><strong>Respostas inadequadas:</strong> aguardar o passageiro perceber sozinho; apenas registrar o não-cumprimento e seguir para o jump seat.</li></ul><h3>Cenário 4 — dinâmica em grupo travada</h3><p><strong>Situação:</strong> em uma dinâmica de grupo, a discussão está travada porque dois candidatos dominam a conversa e os demais não falam. O recrutador observa sem intervir.</p><ul><li><strong>Resposta adequada:</strong> com naturalidade, abrir espaço para quem não falou — <em>Quero ouvir o que os outros pensam sobre isso.</em> Incluir quem está silenciado é o comportamento de liderança mais valorizado em dinâmicas.</li><li><strong>Respostas inadequadas:</strong> aguardar sem intervir; dirigir-se diretamente aos candidatos dominantes pedindo que ouçam os outros.</li></ul><blockquote><p>Recrutadores percebem imediatamente quem inclui e quem exclui no grupo. Essa observação frequentemente decide quem avança — antes mesmo da entrevista individual.</p></blockquote>', 15, 'horsky-hh-115589aa-781d-4ce3-a773-e8b2d280d515'),
  (4, 71, 'Como Montar um Currículo para Aviação', 'Estrutura, formato, linguagem e as escolhas que separam currículos eliminados na triagem automática dos que chegam à entrevista.', '<p>Antes de um humano ver seu currículo, um algoritmo já decidiu seu destino. E antes do algoritmo, suas escolhas de formato e estrutura definem se o conteúdo será lido ou ignorado.</p><h3>O que acontece com seu currículo antes de um humano vê-lo</h3><ul><li><strong>Triagem automática (ATS):</strong> o sistema lê palavras-chave, verifica requisitos básicos e pontua o currículo antes de qualquer humano ver. Currículos com formatação excessiva são rejeitados automaticamente.</li><li><strong>6 segundos de atenção humana:</strong> recrutadores passam em média 6 segundos no primeiro contato com um currículo. O que aparece no topo da primeira página define se haverá uma segunda leitura.</li><li><strong>1 página para iniciantes:</strong> uma página bem estruturada sempre supera duas páginas de conteúdo irrelevante. Síntese é competência.</li><li><strong>Foto é obrigatória na aviação:</strong> foto 3×4 profissional com fundo branco, traje social, sorriso natural, sem filtros.</li></ul><h3>Cabeçalho e dados de contato</h3><p>Nome completo em destaque, cargo-alvo explícito <em>Candidato(a) a Comissário(a) de Voo</em>, e-mail profissional, telefone com DDD e cidade de residência. LinkedIn com URL personalizada é opcional mas valorizado.</p><ul><li><strong>Evite:</strong> e-mails com apelidos como <em>aninha123</em>, redes sociais pessoais como Instagram, omitir a cidade de residência.</li></ul><h3>Objetivo profissional</h3><p>Específico, sem clichês e alinhado ao perfil do edital. Máximo de 3 linhas.</p><ul><li><strong>Errado:</strong> <em>Conseguir emprego de aeromoça pois adoro viajar e tenho facilidade com pessoas.</em></li><li><strong>Correto:</strong> <em>Candidatar-me à posição de comissária de voo, trazendo experiência em atendimento de alto padrão, fluência em inglês e comprometimento com segurança operacional e excelência no serviço ao passageiro.</em></li></ul><h3>Experiência profissional — bullets com resultados</h3><p>Cada bullet deve responder: o que você fez, como e com que resultado. Use números sempre que possível.</p><ul><li><strong>Errado:</strong> <em>Fui responsável por atender clientes na loja e ajudar no estoque.</em></li><li><strong>Correto:</strong> <em>Atendi média de 80 clientes/dia com foco em resolução de conflitos e personalização do atendimento, mantendo NPS de 94% por 8 meses consecutivos.</em></li></ul><h3>Idiomas</h3><p>Use a escala CEFR: A1, A2, B1, B2, C1, C2. Nunca infle o nível de inglês — recrutadores testam ao vivo.</p><ul><li><strong>Errado:</strong> <em>Inglês fluente.</em> sem certificação.</li><li><strong>Correto:</strong> <em>Inglês — Avançado (C1, certificado Cambridge) · Espanhol — Intermediário (B1).</em></li></ul><h3>Informações complementares — específicas da aviação</h3><ul><li>Altura — as companhias têm requisitos mínimos e máximos.</li><li>Disponibilidade para viagens, escalas e pernoites.</li><li>Localização próxima ao aeroporto base quando aplicável.</li><li>Passaporte válido e vacinas em dia.</li></ul><h3>Erros que eliminam imediatamente</h3><ul><li>Nome com emoji ou apelido informal.</li><li>E-mail com apelido e plataforma desatualizada.</li><li>Objetivo genérico com clichê <em>sempre amei viajar</em>.</li><li>Bullets sem resultado — apenas tarefas listadas.</li><li>Nível de inglês inflado — verificado na prova.</li><li>Cursos irrelevantes ocupando espaço valioso.</li></ul>', 14, 'horsky-hh-fef13087-5be1-430d-bab2-8c7582166093'),
  (4, 72, 'Como Funciona o ATS', 'Entenda como sistemas ATS lêem, pontuam e filtram currículos automaticamente — e como garantir que o seu passe por esse filtro invisible.', '<p>Em uma seleção aérea com 2.000 inscrições, o recrutador humano geralmente vê apenas 80 a 150 currículos. O ATS faz o corte inicial sozinho — em segundos, sem empatia e sem contexto.</p><h3>O funil invisível</h3><ul><li><strong>2.000 inscrições recebidas</strong> pela plataforma de vagas.</li><li><strong>800 passam</strong> pelo filtro automático de requisitos: altura, idioma, disponibilidade, escolaridade.</li><li><strong>300 qualificados</strong> após pontuação por palavras-chave: o sistema compara o currículo com o texto da vaga.</li><li><strong>200 legíveis</strong> após verificação de estrutura: currículos com tabelas, colunas ou imagens embutidas são rejeitados.</li><li><strong>80 a 150 chegam</strong> à revisão humana — apenas 10% do total original.</li></ul><h3>Como o ATS lê e pontua seu currículo</h3><ul><li><strong>Extração de texto:</strong> o ATS converte o arquivo em texto puro. Tabelas, colunas e caixas de texto do Word são convertidas de forma imprevisível — frequentemente embaralhando a ordem das informações.</li><li><strong>Matching de palavras-chave:</strong> compara o texto do currículo com o texto da vaga. Termos exatos pesam mais — use as palavras do edital literalmente.</li><li><strong>Posição importa:</strong> palavras-chave no início do documento pesam mais. Um termo no topo pode valer 3× mais que o mesmo termo no final.</li><li><strong>Requisitos eliminatórios:</strong> campos como disponibilidade para viagens e altura funcionam como filtros binários — ausentes no currículo, o candidato é eliminado independentemente do score geral.</li></ul><blockquote><p>Se o edital diz <em>disponibilidade para escalas e pernoites</em>, escreva exatamente isso no currículo — não <em>flexibilidade de horário</em>. O ATS busca correspondências exatas.</p></blockquote><h3>Formatos e compatibilidade com ATS</h3><ul><li><strong>PDF com texto selecionável — recomendado:</strong> texto extraído com precisão, formatação visual preservada, aceito pela maioria das plataformas.</li><li><strong>Word (.docx) sem colunas — aceitável:</strong> alta compatibilidade com ATS, mas visual menos profissional que PDF.</li><li><strong>PDF com colunas ou tabelas — risco:</strong> colunas lidas da esquerda para direita, misturando dados. Nome pode aparecer no meio da experiência.</li><li><strong>Canva, imagem ou PDF escaneado — evite:</strong> ATS não consegue extrair nenhum texto. Score = 0 automaticamente.</li></ul><h3>Elementos que travam o ATS — remova do seu currículo</h3><ul><li>Cabeçalho e rodapé do Word — nome e telefone lá são invisíveis para o ATS.</li><li>Caixas de texto flutuantes.</li><li>Tabelas usadas para organizar o layout.</li><li>Gráficos de barras para indicar nível de idioma.</li><li>Ícones decorativos no lugar de texto.</li><li>Fontes não-padrão ou símbolos especiais.</li></ul><h3>Mitos sobre o ATS</h3><ul><li><strong>Mito:</strong> colocar palavras-chave em branco invisíveis engana o ATS. Os sistemas modernos detectam isso e eliminam o currículo por tentativa de manipulação.</li><li><strong>Mito:</strong> quanto mais palavras-chave, maior o score. Sistemas avançados calculam densidade — repetição excessiva cai o score.</li><li><strong>Mito:</strong> um currículo bonito ganha pontos a mais. O ATS não vê o design — apenas o texto extraído.</li><li><strong>Mito:</strong> pequenas companhias não usam ATS. Plataformas como Gupy e Vagas.com têm ATS embutido independentemente do tamanho da empresa.</li></ul>', 13, 'horsky-hh-f4a54340-c60c-440e-b481-248a2a55058e'),
  (10, 81, 'Postura, Gestos e Contato Visual', 'Aprenda como postura, gestos e contato visual são interpretados em seleções aéreas e como calibrar cada canal para transmitir confiança e presença.', '<p>Recrutadores formam julgamentos nos primeiros segundos de contato — antes de qualquer palavra. Postura, gestos e olhar são os canais que falam por você enquanto você ainda está entrando na sala.</p><h3>Quanto da comunicação não é verbal</h3><p>A percepção de credibilidade e presença é construída em grande parte por sinais não verbais. Os quatro canais de comunicação são:</p><ul><li><strong>Linguagem corporal:</strong> postura, gestos, expressão facial e movimentos físicos — o canal mais imediato e o mais difícil de controlar conscientemente sob pressão.</li><li><strong>Paralinguagem:</strong> volume, ritmo, tom, pausas e qualidade da voz — transmite emoção e intenção independentemente do que as palavras dizem.</li><li><strong>Contato visual:</strong> duração, frequência e direção do olhar — sinaliza confiança, interesse e conexão, ou evasão e desconforto.</li><li><strong>Conteúdo verbal:</strong> as palavras em si — importante, mas interpretadas através do filtro dos três canais acima.</li></ul><blockquote><p>Um comissário que anuncia procedimentos de emergência com voz trêmula e postura retraída transmite o sinal errado — independentemente de o conteúdo estar correto.</p></blockquote><h3>Postura — sinais positivos e negativos</h3><ul><li><strong>Faça:</strong> coluna ereta, ombros levemente para trás sem tensão; pés no chão paralelos ou levemente abertos; tronco levemente inclinado à frente ao ouvir; mãos visíveis e relaxadas; ocupar o espaço da cadeira sem deslizar para o limite.</li><li><strong>Evite:</strong> ombros curvados para frente; braços cruzados; pernas muito abertas ou cruzadas repetidamente; encostar-se à parede ou móvel enquanto espera; balançar o corpo ou tamborilar dedos.</li></ul><p><strong>Exercício de postura:</strong> encoste o ombro esquerdo na parede, depois o direito. Afaste-se 5 cm. Essa é a posição natural dos ombros. Pratique em frente ao espelho por 30 segundos antes de qualquer seleção.</p><h3>Gestos — o que comunicar e o que evitar</h3><ul><li><strong>Gestos que comunicam presença:</strong> mãos abertas com palmas visíveis; gesto de enumeração com dedos; aceno leve de cabeça ao ouvir; gestos contidos no espaço entre peito e cintura.</li><li><strong>Gestos que distraem:</strong> tocar o rosto, cabelo ou pescoço repetidamente; gesticular excessivamente acima dos ombros; apontar o dedo indicador para o interlocutor; mexer em objetos durante a fala.</li></ul><p><strong>Técnica das mãos neutras:</strong> una levemente as pontas dos dedos das duas mãos em posição de torre. É discreto, controlado e transmite segurança — funciona em pé e sentado.</p><h3>Contato visual — calibração ideal</h3><p>A zona ideal é entre 60% e 70% do tempo de contato durante a conversa.</p><ul><li><strong>Use:</strong> manter contato ao iniciar e finalizar respostas; quebrar o contato lateralmente — não para baixo — ao pensar; distribuir o olhar entre todos em grupos; sorrir levemente com os olhos.</li><li><strong>Evite:</strong> olhar para baixo frequentemente; olhar fixo sem piscar; olhar para a porta ou janela; ignorar parte do grupo ao falar em dinâmica.</li></ul><p><strong>Técnica do triângulo:</strong> trace mentalmente um triângulo entre olho esquerdo, olho direito e boca do interlocutor. Alterne o foco suavemente entre esses três pontos — o efeito é contato visual caloroso e natural sem intimidação.</p>', 15, 'horsky-hh-cf0a4337-9dea-401b-98ea-3f53b94001bb'),
  (10, 82, 'Voz, Ritmo e Coerência entre Canais', 'Aprenda a calibrar volume, ritmo e tom de voz para cada situação e a garantir coerência entre o que você diz e como o seu corpo o diz.', '<p>A voz é avaliada em quatro dimensões independentes: volume, ritmo, tom e pausa. Conteúdo perfeito entregue com voz trêmula ou monocórdica perde credibilidade. O sinal mais prejudicial não é a postura incorreta isolada — é a incoerência entre o que você diz e o que seu corpo mostra.</p><h3>Configurações ideais de voz</h3><ul><li><strong>Volume:</strong> audível sem esforço — a outra pessoa não precisa pedir para repetir.</li><li><strong>Ritmo:</strong> 130 a 150 palavras por minuto em entrevista — confortável de ouvir.</li><li><strong>Tom final das frases:</strong> descendente em frases assertivas — transmite convicção. Tom ascendente no fim faz tudo soar como pergunta.</li><li><strong>Pausas:</strong> 1 a 2 segundos antes de responder demonstra reflexão, não hesitação.</li><li><strong>Variação:</strong> mudar o ritmo para enfatizar pontos importantes — tom monocórdico parece desinteresse ou leitura decorada.</li></ul><ul><li><strong>Evite:</strong> falar sem pausas — sinaliza nervosismo; voz muito baixa — interpretada como timidez; preenchidores como <em>ééé</em>, <em>tipo</em>, <em>né</em>.</li></ul><p><strong>Técnica da pausa intencional:</strong> quando fizer uma pergunta a você, expire silenciosamente antes de responder. A pausa de 2 segundos transmite reflexão e controle — pratique em situações cotidianas.</p><h3>Entrega vocal por situação</h3><ul><li><strong>Apresentação pessoal:</strong> volume médio-alto, ritmo moderado, tom descendente no fim. Faça pausa de 1 segundo antes de começar. Comece pelo nome em tom firme.</li><li><strong>Situação de pressão:</strong> volume estável, ritmo lento e pausado, tom firme e neutro. A calma na voz durante o relato prova que você realmente tem controle emocional.</li><li><strong>Trabalho em equipe:</strong> volume caloroso, ritmo natural e fluido. Distribua o olhar para todos ao dizer essa frase — o gesto de inclusão reforça as palavras.</li><li><strong>Comando de emergência:</strong> volume alto e claro, ritmo deliberado, tom autoritativo. Use voz mais alta que o normal, ritmo mais lento e pausas entre comandos.</li></ul><h3>Coerência entre canais — quando o corpo contradiz a voz</h3><ul><li><strong>Canais alinhados:</strong> diz <em>estou muito motivado</em> e sorri, postura ereta, voz firme. Diz <em>sei trabalhar em equipe</em> e olha para todos no grupo.</li><li><strong>Canais em conflito:</strong> diz <em>estou tranquilo</em> com voz trêmula, mão no rosto e perna balançando. Diz <em>sou comunicativo</em> mas responde em monossílabos e evita contato visual.</li></ul><blockquote><p>Quando há conflito entre o que você diz e como diz, o interlocutor acredita no corpo — não nas palavras. Pratique em voz alta e se grave: você vai perceber incoerências que não sente na hora.</p></blockquote><h3>Checklist de espelho — pratique antes da seleção</h3><ul><li>Manteve coluna ereta sem tensão por mais de 2 minutos.</li><li>Fez pausa antes de responder cada pergunta.</li><li>Terminou frases assertivas com tom descendente.</li><li>Não usou ééé, tipo ou né como preenchidores.</li><li>Manteve contato visual ao iniciar e finalizar respostas.</li><li>Quebrou o contato lateralmente, não para baixo.</li><li>A expressão facial correspondia ao conteúdo da fala.</li><li>Não tocou o rosto ou cabelo durante a prática.</li><li>Gravou e assistiu pelo menos 1 minuto de si mesmo.</li></ul>', 13, 'horsky-hh-005baffb-91fc-4178-82ab-5abf1a7a6559'),
  (11, 91, 'Guia de Preparação para o Dia da Seleção', 'Checklist completo do que preparar, levar e como se comportar desde a véspera até a saída do local de seleção.', '<p>Antes de um humano ver seu currículo, um algoritmo já decidiu. E antes do dia da seleção, suas escolhas de preparação já definem boa parte do resultado. Este guia cobre tudo — da véspera à saída do prédio.</p><h3>Documentos e comprovantes — o que levar</h3><ul><li>RG e CPF originais — leve também cópia, algumas empresas pedem.</li><li>Currículo impresso em duas vias no mínimo, em papel branco, fonte limpa, com foto profissional.</li><li>Comprovante de escolaridade: diploma ou histórico.</li><li>Foto 3×4 recente com fundo branco.</li><li>Comprovante de residência atualizado.</li><li>Certificado de inglês, se houver.</li><li>Confirmação de inscrição ou convite da empresa — impresso ou salvo offline.</li><li>Carteira de vacinação, se solicitado no edital.</li></ul><h3>Apresentação pessoal</h3><ul><li>Roupa selecionada, passada e alinhada ao padrão da empresa — social discreto, cores neutras.</li><li>Sapatos limpos e conservados — salto no máximo 7 cm.</li><li>Cabelo arrumado — coque ou preso para mulheres, curto e alinhado para homens.</li><li>Maquiagem discreta quando aplicável: batom neutro, olho suave.</li><li>Unhas cuidadas — curtas ou esmalte neutro ou francês.</li><li>Perfume leve — uma aplicação apenas.</li><li>Acessórios discretos: brincos pequenos, relógio simples.</li></ul><h3>Roteiro hora a hora</h3><ul><li><strong>Véspera — noite:</strong> separe roupa, documentos, bolsa e itens de higiene. Revise as frases-chave de apresentação. Durma cedo — aparência descansada é percebida.</li><li><strong>Manhã do dia — 3h antes:</strong> café da manhã leve. Evite perfume intenso. Vista-se com cuidado e verifique cada detalhe no espelho antes de sair.</li><li><strong>Chegada — 30 min antes:</strong> use o tempo extra para respirar, observar o ambiente e acomodar-se. Chegada atrasada elimina imediatamente.</li><li><strong>Recepção:</strong> cumprimente a recepcionista com simpatia. Postura ereta na cadeira, telefone guardado, sorriso natural. A seleção começa aqui.</li><li><strong>Dinâmica em grupo:</strong> contribua com equilíbrio, escute ativamente, inclua quem está calado, mantenha energia mesmo nas atividades mais longas.</li><li><strong>Entrevista individual:</strong> responda com estrutura situação, ação, resultado. Conheça a empresa. Tenha uma razão genuína para querer fazer parte dela.</li><li><strong>Saída:</strong> agradeça a todos com quem interagiu. Saia com a mesma postura e energia da entrada — recrutadores observam candidatos até saírem do prédio.</li></ul><h3>Postura e comportamento geral</h3><ul><li>Celular no silencioso e guardado durante todo o processo.</li><li>Postura ereta na cadeira na sala de espera.</li><li>Não formar grupos ou fofocas sobre outros candidatos.</li><li>Usar linguagem formal e sem gírias desde o primeiro contato.</li><li>Manter sorriso natural e expressão positiva mesmo nos momentos de espera.</li></ul><blockquote><p>Recrutadores frequentemente decidem candidatos com base no que observam nos momentos não estruturados. A seleção começa antes de você entrar na sala — e termina depois de você sair.</p></blockquote>', 11, 'horsky-hh-a528a50c-517b-47cf-b427-cc53369eb0b7'),
  (11, 92, 'Simulado Final — Perguntas e Respostas', 'Pratique as perguntas mais frequentes de entrevistas aéreas com respostas modelo estruturadas pelo método STAR e análise do que funciona em cada uma.', '<h2>Simulado Final — Perguntas e Respostas de Entrevista</h2><p>As perguntas de entrevista em seleções aéreas seguem padrões identificáveis. Conhecer a estrutura de cada tipo de pergunta e o que o recrutador está avaliando por trás dela transforma respostas genéricas em respostas que convencem.</p><h3>O método STAR</h3><p>A maioria das perguntas comportamentais pede uma narrativa estruturada. O método STAR organiza essa narrativa em quatro partes:</p><ul><li><strong>S — Situação:</strong> contexto breve em que o evento ocorreu.</li><li><strong>T — Tarefa:</strong> o que você precisava fazer ou resolver.</li><li><strong>A — Ação:</strong> o que você concretamente fez — esta é a parte mais importante.</li><li><strong>R — Resultado:</strong> o que aconteceu — preferencialmente com indicadores concretos.</li></ul><h3>Pergunta 1 — Por que quer ser comissário(a)?</h3><ul><li><strong>O que o recrutador avalia:</strong> motivação genuína, conhecimento da profissão, alinhamento com os valores da empresa.</li><li><strong>Resposta fraca:</strong> <em>Sempre amei viajar e quero conhecer o mundo.</em></li><li><strong>Resposta forte:</strong> <em>Me identifico com atendimento de alto padrão e com ambientes que exigem precisão e cuidado com pessoas ao mesmo tempo. Tenho experiência em serviço ao cliente em situações de pressão e quero crescer em um contexto onde cada detalhe importa — como a aviação exige. Pesquisei muito a [nome da empresa] e me identifiquei especialmente com [valor ou característica específica da companhia].</em></li></ul><h3>Pergunta 2 — Fale sobre uma situação difícil que você superou</h3><ul><li><strong>O que o recrutador avalia:</strong> gestão de pressão, inteligência emocional, capacidade de resolução de problemas.</li><li><strong>Resposta forte (usando STAR):</strong> <em>Trabalhava em hotel e um hóspede chegou muito alterado porque sua reserva tinha sido cancelada por erro do sistema, no dia do check-in. [S] Eu precisava resolver a situação sem comprometer a experiência dos outros hóspedes ao redor. [T] Convidei o hóspede para uma conversa reservada, ouvi tudo com atenção e acionei o gerente imediatamente. Em paralelo, consultei outras opções de acomodação disponíveis. [A] O hóspede foi realocado em 20 minutos e recebeu um upgrade. Ele voltou a se hospedar duas vezes no mesmo ano. [R]</em></li></ul><h3>Pergunta 3 — Qual é o seu maior defeito?</h3><ul><li><strong>O que o recrutador avalia:</strong> autoconsciência, honestidade, capacidade de desenvolvimento.</li><li><strong>Resposta fraca:</strong> <em>Sou perfeccionista demais.</em> — resposta percebida como evasiva e ensaiada.</li><li><strong>Resposta forte:</strong> <em>Tenho dificuldade de delegar quando confio muito no resultado do meu próprio trabalho. Tenho trabalhado nisso conscientemente — aprendi que confiar no colega é parte do trabalho em equipe, não uma fraqueza. No último projeto em equipe, me forcei a distribuir tarefas desde o início e o resultado foi melhor do que teria sido se eu tivesse tentado controlar tudo.</em></li></ul><h3>Pergunta 4 — Como você age quando discorda do seu superior?</h3><ul><li><strong>O que o recrutador avalia:</strong> respeito à hierarquia, comunicação assertiva, maturidade profissional.</li><li><strong>Resposta forte:</strong> <em>Creio que discordâncias são parte saudável de qualquer equipe, mas o momento e a forma de expressá-las importam muito. No contexto operacional, sigo o protocolo e o comando da liderança. Se tiver uma opinião diferente, comunico em momento adequado — fora da situação de pressão — de forma respeitosa e com base em argumento concreto. Na aviação especialmente, entendo que a hierarquia existe por razões de segurança.</em></li></ul><h3>Pergunta 5 — Você tem alguma pergunta para nós?</h3><ul><li><strong>O que o recrutador avalia:</strong> interesse genuíno na empresa, preparo e curiosidade profissional.</li><li><strong>Resposta fraca:</strong> <em>Não, acho que foi tudo respondido.</em></li><li><strong>Respostas fortes:</strong> <em>Como é o processo de desenvolvimento dos comissários nos primeiros meses após o CRM?</em> / <em>Quais são as características que os comissários de melhor desempenho têm em comum na empresa?</em></li></ul><blockquote><p>A última pergunta que você faz é o último sinal que você deixa. Use-a para demonstrar que você já pensa como parte da empresa — não como alguém esperando para entrar.</p></blockquote>', 18, 'horsky-hh-0795eb55-0a7a-4542-9f59-69db569482a9'),
  (12, 11, 'O que significa vestir o uniforme pela primeira vez', 'O uniforme não é só uma roupa de trabalho. Ele representa a companhia aérea e a sua responsabilidade perante clientes, colegas e a sociedade.', '<img src="/img/aulas/conduta/1779141900938-cxwmd3hha.jpg" loading="lazy" /><p>Vou ser direto com você: no dia em que você colocou o uniforme pela primeira vez, algo mudou e não é só a roupa.</p><p>A partir daquele momento, você parou de ser "apenas você" em determinados contextos. Você virou a cara da empresa. Isso parece exagerado? Não é.</p><p>Pensa bem: quando um passageiro vê você de uniforme num restaurante, num mercado, num aeroporto ele não vê "a Fernanda" ou "o João". Ele vê o nome da companhia bordado na lapela. E o comportamento dele passa a ser moldado pela experiência que você vai proporcionar ali, mesmo que seja uma interação de 30 segundos num corredor.</p><p>Isso tem um lado bonito: você representa algo maior do que você. Uma empresa, uma categoria, uma profissão que é admirada. Mas tem um lado que exige maturidade: você não pode desligar isso quando quiser.</p><p>Muita gente entra na aviação achando que vai poder comemorar a contratação do jeito que sempre comemorou tudo na vida com post no Instagram, stories empolgados, foto com a galera. E tudo bem ter esse entusiasmo. O problema é quando esse entusiasmo não leva em conta o peso que o uniforme carrega.</p><p>Já aconteceu de colaboradores serem chamados na gerência antes mesmo do primeiro voo por causa de um post feito no mesmo dia da contratação. Um print de material de treinamento. Uma foto dentro de uma área restrita. Um comentário animado sobre algo que era confidencial.</p><p>Então guarda isso como primeiro aprendizado: o uniforme é um privilégio. E privilégio vem com responsabilidade. Não existe <strong><em>"estou de folga, então posso fazer o que quiser de uniforme".</em></strong> Não funciona assim na aviação.</p>', 10, 'horsky-conduta-80920b68-4a78-4bc9-accd-fbd69a9d309e'),
  (12, 12, 'Ser aprovado(a) é o começo, não a chegada', 'Muita gente confunde aprovação no processo seletivo com liberdade para agir como quiser. Aqui a gente esclarece o que a empresa espera de você desde o primeiro dia.', '<img src="/img/aulas/conduta/1779141933555-kf21ycrq1.jpg" loading="lazy" /><p>Quero que você entenda uma coisa que ninguém fala abertamente nos processos seletivos: passar na seleção é a parte mais fácil.</p><p>Parece duro dizer isso, mas é verdade. O processo seletivo avalia o que você é em algumas horas de entrevista, dinâmica e avaliação. O dia a dia de trabalho vai avaliar quem você é durante meses e anos nas escalas cansativas, nas situações de estresse, nas relações com colegas difíceis, nas tentações de postar algo que não devia.</p><p>A empresa não para de te observar depois que você assina o contrato. Na verdade, o período de experiência é onde a maioria das decisões reais sobre o seu futuro ali são tomadas. Líderes, chefes de cabine, instrutores todos estão, conscientemente ou não, formando uma opinião sobre você.</p><p>E não é só o que você faz dentro do avião. É como você chega para o treinamento. Se você aparece no horário ou sempre atrasado(a). Se você faz perguntas pertinentes ou fica no celular. Se você trata os colegas com respeito ou já começa a criar grupinhos e fofoca.</p><p>Tem um comportamento específico que sempre chama atenção negativamente: o colaborador que, mal contratado, já age como se tivesse chegado. Que fala mal da escala, que questiona tudo sem ter experiência ainda, que acha que já sabe como as coisas funcionam.</p><p>A postura certa é a oposta: chegar com humildade, disposição para aprender e consciência de que você ainda tem muito para descobrir sobre essa profissão. Os melhores profissionais da aviação que conheço foram os que entraram assim — e continuaram assim mesmo depois de anos de experiência.</p>', 10, 'horsky-conduta-9f105df5-de23-4b97-9ff2-a2a0ecedb59d'),
  (12, 13, 'Por que as regras existem — e por que você precisa segui-las', 'A aviação é um dos setores mais regulados do mundo. Entender o porquê de cada regra muda completamente a relação que você tem com elas.', '<img src="/img/aulas/conduta/1779141970459-q82gb1gfp.jpg" loading="lazy" /><p>Tem uma frase que eu repito bastante para turmas novas: na aviação, as regras não foram escritas por burocratas. Elas foram escritas com sangue.</p><p>Isso pode soar pesado, mas é literalmente verdade. Grande parte dos procedimentos de segurança que existem hoje tanto na operação quanto na conduta dos tripulantes nasceu de incidentes, acidentes e erros que custaram muito caro. Às vezes, custaram vidas.</p><p>Então quando alguém te diz "você não pode fazer isso" ou "esse procedimento tem que ser exatamente assim", a resposta não é questionar se faz sentido pra você naquele momento. A resposta é seguir. E depois, se ainda tiver dúvida, buscar entender o porquê pelos canais certos.</p><p>Agora, além da segurança operacional, existem as regras de conduta. E aqui entra um ponto importante: descumprir uma regra de conduta pode sim resultar em demissão por justa causa o que na prática significa que você sai sem os direitos trabalhistas e com uma mancha no histórico profissional que vai te seguir.</p><p>Já vi pessoas perderem emprego por coisas que pareciam pequenas: uma foto postada sem autorização, um comentário numa rede social, usar o benefício de passagem de forma errada, omitir um relacionamento com colega.</p><p>Nenhuma dessas pessoas acordou aquele dia pensando "hoje vou fazer algo que vai me custar o emprego". Aconteceu por descuido, por não saber a regra ou por achar que não era pra tanto.</p><p>É por isso que este treinamento existe. Para que você saiba. E sabendo, não tenha desculpa.</p>', 10, 'horsky-conduta-f574bdc6-dfff-4f49-8654-e447ca370c50'),
  (12, 14, 'Hierarquia a bordo: como ela funciona na prática', 'A bordo existe uma estrutura clara de comando. Respeitar essa estrutura não é questão de ego — é questão de segurança.', '<img src="/img/aulas/conduta/1779141991952-rr22pqf57.jpg" loading="lazy" /><p>Vou te apresentar uma das coisas que mais gera conflito entre comissários(as) iniciantes: a hierarquia a bordo.</p><p>A estrutura é assim: no topo está o Comandante, que tem autoridade máxima sobre tudo e todos dentro da aeronave durante o voo. Abaixo dele, o Copiloto. Na cabine de passageiros, o Chefe de Cabine é o responsável pela equipe de comissários e você reporta diretamente a ele durante o voo.</p><p>Parece simples. E é. O problema é quando alguém acha que hierarquia é coisa de ego, ou que se uma orientação não faz sentido pra ela, ela pode simplesmente não seguir.</p><p>Na aviação, não funciona assim. Durante o voo, a hierarquia é seguida. Ponto. Se você discorda de algo, o momento de falar é antes do voo ou depois nunca durante, exceto em situações que envolvam risco real à segurança.</p><p>E olha, isso não é sobre submissão cega. É sobre entender que num ambiente de alta pressão, com dezenas de passageiros a bordo e variáveis que mudam o tempo todo, todo mundo precisa saber exatamente quem decide o quê. Quando isso não está claro, erros acontecem.</p><p>Um ponto que eu sempre reforço: respeitar hierarquia não significa engolir assédio ou situação de abuso. Se um superior age de forma inadequada com você, existe canal para isso e você deve usar. Mas discordância profissional sobre um procedimento? Isso vai para o briefing ou para o debriefing, nunca para uma discussão no corredor da aeronave com passageiros ao redor.</p>', 10, 'horsky-conduta-44ffc08f-e41f-49b5-9768-b76ce8908b80'),
  (12, 15, 'Sua reputação começa antes do primeiro voo', 'A imagem que você constrói no treinamento, nas redes sociais e nas conversas do dia a dia define como você vai ser visto(a) na empresa.', '<img src="/img/aulas/conduta/1779142520183-1h35vixvu.jpg" loading="lazy" /><p>Deixa eu te contar algo que a maioria dos instrutores não fala na primeira semana: sua reputação dentro da empresa já começou a ser construída e você talvez nem tenha percebido.</p><p>Como você se apresentou no primeiro dia de treinamento. Se veio no horário. Se estava com aparência alinhada com o que a empresa espera. Como tratou a pessoa da recepção. Se ficou no celular durante a aula ou prestou atenção. Tudo isso está sendo processado pelas pessoas ao seu redor.</p><p>E não estou falando de paranoia. Estou falando de algo natural: as pessoas formam impressões. E numa empresa onde escalas são feitas com base em confiança, onde promoções dependem de quem te conhece e te recomenda, essas impressões importam muito.</p><p>Nas redes sociais, isso tem um peso ainda maior. A gente vai falar bastante sobre redes sociais no próximo módulo, mas já deixo um aviso: o que você posta durante o treinamento pode chegar ao RH antes de você chegar ao primeiro voo.</p><p>Material de aula fotografado e postado. Comentários empolgados sobre conteúdos que são internos. Print de conversas do grupo da turma. Tudo isso já aconteceu com pessoas reais, em empresas reais, com consequências reais.</p><p>Então meu conselho para você, agora, neste início de carreira: invista mais energia em ser reconhecido(a) como alguém confiável, comprometido(a) e discreto(a) do que em construir uma narrativa nas redes sobre a nova fase. A narrativa mais bonita vai ser construída ao longo dos anos, com consistência. Esse é o tipo de história que dura.</p>', 10, 'horsky-conduta-4f65406a-24e7-4c78-8535-9cc4a95121a5'),
  (12, 21, 'A empresa monitora. E a internet não esquece.', 'O que você posta hoje pode ser encontrado amanhã, daqui a um ano ou daqui a dez anos. E sim, as empresas monitoram colaboradores nas redes sociais.', '<img src="/img/aulas/conduta/1779142534151-9rjgvrlxg.jpg" loading="lazy" /><p>Vou ser muito honesto com você aqui: as empresas aéreas monitoram colaboradores nas redes sociais. Não é teoria, não é especulação. É realidade.</p><p>Existe software específico para isso. Existem pessoas que fazem isso como parte do trabalho delas. E existe também algo mais simples e mais comum do que tudo isso: outros colaboradores, passageiros e pessoas da sua rede que veem o que você posta e encaminham para a empresa.</p><p>Você pode estar pensando "mas meu perfil é privado". Privado não significa invisível. Significa que você escolheu quem pode ver mas não tem controle sobre o que essas pessoas fazem com o que veem. Um print de um story que sumiu em 24 horas pode circular por meses.</p><p>Já acompanhei situações em que um vídeo postado por uma comissária viralizou em menos de 48 horas. O vídeo mostrava o interior da aeronave antes do embarque, com a colaboradora comentando sobre o caos de uma escala apertada. O tom era desabafo, não malícia. Mas o resultado foi demissão por justa causa porque ela expôs informações operacionais e prejudicou a imagem da companhia.</p><p>E ela achou que estava só conversando com os seguidores.</p><p>O ponto que quero que você leve daqui é simples: antes de postar qualquer coisa que tenha relação com o seu trabalho — direta ou indiretamente faz uma pergunta: "Se o meu gestor vir isso agora, o que vai acontecer?" Se a resposta for incerta, não posta. Não vale o risco.</p>', 10, 'horsky-conduta-fb8d2e9e-c433-4620-a721-d0c40b1b5435'),
  (12, 22, 'Uniformizado(a) nas redes: o que nunca fazer', 'Uma lista clara do que é absolutamente proibido postar quando você está de uniforme, com crachá ou em qualquer ambiente da empresa.', '<img src="/img/aulas/conduta/1779142554281-fwmgyn8gy.jpg" loading="lazy" /><p><br>Vamos direto ao ponto porque esse assunto não tem meio-termo.</p><p>Quando você está de uniforme ou com crachá, colete, qualquer peça que identifique você como colaborador(a) da empresa existe uma lista de coisas que simplesmente não podem aparecer nas suas redes. Não tem contexto que justifique. Não tem "mas era só uma brincadeira". Não tem "o grupo era fechado".</p><p>Foto ou vídeo com bebida alcoólica de uniforme: justa causa. Simples assim. Não importa se você estava fora do horário de trabalho, num aniversário de amigo, num happy hour depois da escala. O uniforme transforma você em representante da empresa naquele momento.</p><p>Comentários sobre atrasos, cancelamentos, problemas de voo ou qualquer situação operacional: proibido. Isso inclui stories do tipo "que dia hein" com emoji de avião quando o voo atrasou. Inclui comentários em posts de passageiros reclamando. Inclui qualquer coisa que coloque você no meio de uma discussão sobre a operação da empresa.</p><p>Opiniões políticas, religiosas ou sociais quando há qualquer identificação com a empresa: proibido. Você pode ter a opinião que quiser na sua vida pessoal. Mas quando o uniforme aparece junto, a opinião deixa de ser sua e passa a ser da empresa — e a empresa não pode ter esse tipo de posicionamento público.</p><p>Publicidade de marcas parceiras usando a imagem de colaborador(a): proibido sem autorização. Mesmo que a marca seja parceira da empresa, mesmo que pareça positivo. Sem autorização formal do Marketing, não rola.</p><p>Conteúdo adulto, jogos de azar, apostas com qualquer referência à empresa: proibido e com consequências gravíssimas.</p><p>Guarda essa regra: uniforme é empresa. Se está de uniforme e posta, a empresa está postando. O que quer que seja.</p>', 10, 'horsky-conduta-3ea0505a-d660-40a2-bf7e-d933a2a5f6b2'),
  (12, 23, 'O que é informação confidencial — e por que você acessa mais do que imagina', 'Durante o trabalho, você tem acesso a um volume grande de informações que não podem sair da empresa. Entenda quais são e por que isso é tão sério.', '<img src="/img/aulas/conduta/1779142568805-r3gq6atm8.jpg" loading="lazy" /><p>Deixa eu te surpreender com uma coisa: você vai ter acesso a muito mais informação confidencial do que imagina na sua função.</p><p>Dados de passageiros nome, destino, assento, necessidades especiais, forma de pagamento. Situações operacionais atrasos que ainda não foram comunicados, problemas técnicos, decisões do comandante. Conversas entre tripulantes sobre situações de voo. Informações sobre rotas, escalas e estratégias que ainda não são públicas.</p><p>Tudo isso passa pela sua rotina de trabalho. E nada disso pode sair dali.</p><p>O caso mais delicado e que acontece com mais frequência do que parece é o do passageiro famoso. Quando uma celebridade, político ou pessoa pública embarca, é natural que a informação circule entre a tripulação. O problema é quando isso sai para fora.</p><p>Uma comissária enviou mensagem no grupo de WhatsApp dos colegas contando o nome, o assento e o destino de um artista famoso que estava a bordo. A mensagem vazou. A empresa foi acionada juridicamente. A comissária respondeu processo.</p><p>Ela não quis prejudicar ninguém. Ela só não pensou nas consequências.</p><p>Outra situação que acontece muito: fotografar passageiros sem consentimento. Um passageiro dormindo numa posição engraçada, alguém comendo de forma curiosa, uma criança fazendo algo fofo. Parece inofensivo. Mas é violação de privacidade e dependendo do que acontecer com essa foto, pode resultar em processo judicial.</p><p>A regra é uma só: o que você vê e ouve no trabalho fica no trabalho.</p>', 10, 'horsky-conduta-a1179648-3464-4675-abc2-b85eb5733c6a'),
  (12, 24, 'Você pode ter redes sociais — e pode postar sobre a profissão', 'Ter redes sociais não é proibido. O problema é como usá-las. Aqui você aprende a manter presença digital sem colocar a carreira em risco.', '<img src="/img/aulas/conduta/1779142586099-r5b8x407v.jpg" loading="lazy" /><p>Agora que eu falei tudo que não pode, deixa eu falar o que pode porque a ideia não é te assustar, é te preparar.</p><p>Você pode ter redes sociais. Você pode postar sobre sua vida, sobre viagens, sobre destinos incríveis que você vai conhecer nessa profissão. Você pode ser criador(a) de conteúdo se quiser. Tem comissários(as) com centenas de milhares de seguidores que fazem isso de forma profissional e com o reconhecimento da empresa.</p><p>A diferença está em como fazer isso.</p><p>O que funciona: conteúdo sobre destinos que você visitou, sem mencionar detalhes operacionais. Dicas de viagem da perspectiva de quem vive no ar. Bastidores permitidos que a empresa autorizou formalmente ou que claramente não expõem nada sensível. Sua rotina de viajante, sua evolução na carreira, seus aprendizados pessoais.</p><p>O que não funciona: mostrar o interior da aeronave sem autorização. Comentar sobre a operação, mesmo que positivamente "hoje o voo foi perfeito" com o número do voo e a rota já é informação operacional. Aparecer de uniforme em contextos que não foram pensados para isso.</p><p>Uma dica prática: separe mentalmente "eu, a pessoa" de "eu, o(a) comissário(a)". Quando você posta como pessoa — nos seus destinos, na sua vida fora do trabalho, sem nenhuma referência à empresa você tem bem mais liberdade. Quando você posta como comissário(a) com uniforme, crachá, dentro da aeronave você está em terreno que exige cuidado.</p><p>E se você quiser crescer como criador(a) de conteúdo na aviação, o caminho certo é conversar com a área de Comunicação da empresa. Tem gente que faz isso de forma oficial e muito bem-feita.</p>', 10, 'horsky-conduta-f7e94616-325b-4ee7-85b9-75d6ec661649'),
  (12, 25, 'Quando colegas erram nas redes: o que você faz com isso', 'O que fazer quando você vê um colega postando algo inadequado que pode prejudicar a empresa, a equipe e a carreira dele.', '<img src="/img/aulas/conduta/1779142620636-2gvpxzboq.jpg" loading="lazy" /><p>Essa situação vai acontecer com você. Pode ter certeza. Em algum momento, você vai ver um colega postando algo que claramente não devia.</p><p>E aí vem uma decisão que parece pequena mas não é: o que você faz?</p><p>A primeira coisa que eu quero que você entenda é que existir esse tipo de situação gera um risco coletivo. Quando um post negativo viraliza, o nome da empresa vai junto — e todo mundo que trabalha ali é afetado de alguma forma. Então isso não é "problema do colega". É um problema que pode respingar em você e em toda a equipe.</p><p>A segunda coisa: curtir, compartilhar ou comentar em posts inadequados de colegas pode te colocar na mesma situação. Já aconteceu de colaboradores serem identificados por terem curtido um conteúdo problemático. Parece absurdo? É o mundo real das redes sociais.</p><p>O que fazer quando você vê: primeiro, tente conversar com o colega diretamente se tiver esse tipo de proximidade. Um "ei, acho que isso pode gerar problema, você já pensou nisso?" pode salvar a carreira de alguém. Se não tiver essa proximidade, ou se o conteúdo for grave, use o canal de denúncias da empresa — que é anônimo e existe exatamente para isso.</p><p>O que não fazer: ignorar achando que não é problema seu. Compartilhar porque achou engraçado. Comentar algo que te associe ao conteúdo.</p><p>E uma última coisa sobre isso: usar o canal de denúncias para reportar algo que você viu não é traição. É profissionalismo. Há uma diferença enorme entre fofoca e reporte legítimo de algo que pode causar dano. Você vai aprender a distinguir isso com o tempo.</p>', 10, 'horsky-conduta-3282bcd5-3333-40e0-a7d5-726ff98e79ca'),
  (12, 31, 'Escalas e pernoites: liberdade com responsabilidade', 'Durante escalas e pernoites, você ainda representa a empresa. E mais do que isso, você tem uma responsabilidade com a segurança do próximo voo.', '<img src="/img/aulas/conduta/1779142749726-upcfhxggv.jpg" loading="lazy" /><p>A escala é um dos momentos mais aguardados na vida de quem está começando na aviação. Você chega numa cidade nova, tem algumas horas livres, quer aproveitar. E tudo bem faz parte da profissão e é um dos maiores privilégios dela.</p><p>Mas tem uma coisa que eu preciso que você entenda desde cedo: o descanso durante a escala não é opcional. Ele é parte do seu trabalho.</p><p>Quando você embarca no próximo voo, você tem a vida de dezenas ou centenas de pessoas nas mãos. Não no sentido dramático mas no sentido real de que um comissário(a) cansado(a), desidratado(a) ou com reflexos comprometidos por uma noite mal dormida pode não reagir adequadamente numa emergência. E emergências na aviação existem.</p><p>Então quando a escala é curta e o próximo voo é cedo, a escolha responsável é descansar. Não é a escolha mais divertida. Mas é a escolha certa.</p><p>Sobre álcool durante a escala: existe uma diferença entre tomar uma taça de vinho num jantar tranquilo e passar a noite numa festa. A empresa não vai medir o que você fez hora por hora. Mas se você chegar para o próximo voo com sinais de que não dormiu ou de que consumiu álcool em excesso, você pode ser afastado(a) e dependendo da situação, as consequências vão muito além do afastamento.</p><p>Já acompanhei casos em que equipes inteiras foram comprometidas por causa de dois ou três tripulantes que não respeitaram esse limite numa escala. O voo foi adiado, passageiros foram prejudicados, e os envolvidos responderam processo administrativo.</p><p>Aproveite as escalas. Elas são incríveis. Só lembre que o próximo voo sempre está na equação.</p>', 10, 'horsky-conduta-d2f5b9dc-9122-4fbb-9833-e978f9e34f09'),
  (12, 32, 'Álcool e drogas: tolerância zero não é exagero', 'As regras sobre álcool e drogas na aviação são das mais rígidas do mundo. Entenda por que e o que está em jogo.', '<img src="/img/aulas/conduta/1779142765139-ispwrcc7m.jpg" loading="lazy" /><p>Vou falar sobre um tema que muita gente acha que só se aplica a pilotos. Spoiler: não é.</p><p>As regras sobre álcool e drogas na aviação valem para toda a tripulação e são absolutas. Não existe "só um pouco". Não existe "mas eu não estava sentindo nada". Existe o resultado do teste, e o resultado manda.</p><p>As empresas realizam testes toxicológicos de forma aleatória e também quando há suspeita. Antes de determinados voos, em fiscalizações de autoridades aeronáuticas, em situações pós-incidente. Você não sabe quando vai ser chamado(a). E não precisa saber porque se você está dentro das regras, não tem problema.</p><p>O que muita gente não sabe é que medicamentos prescritos também entram nessa conta. Se você usa algum remédio de forma contínua ansiolítico, antidepressivo, antihistamínico, qualquer coisa — você precisa informar ao médico do trabalho da empresa antes de voar. Não para ser julgado(a). Para garantir que aquela medicação é compatível com as suas funções e que você está protegido(a) se um teste acontecer.</p><p>Uma comissária foi afastada não porque estava usando droga ilegal, mas porque tomava um medicamento controlado com receita médica e não havia comunicado à empresa. O teste deu positivo para a substância e, por não ter o registro interno, ela passou por todo um processo de regularização antes de poder voltar a voar.</p><p>Burocrático? Um pouco. Mas completamente evitável com uma simples conversa com o médico do trabalho.</p><p>A regra é clara: apresente-se ao trabalho em plenas condições físicas e mentais. Sempre.</p>', 10, 'horsky-conduta-ed8adafa-8e23-4576-8fd2-a614086bdf0c'),
  (12, 33, 'Relacionamentos com colegas: o que a empresa precisa saber', 'Relacionamentos afetivos entre colegas são naturais. Mas na aviação existem regras claras sobre como isso deve ser declarado e gerenciado.', '<img src="/img/aulas/conduta/1779142798016-0tl3cd0lj.jpg" loading="lazy" /><p>Olha, vou falar de um assunto que gera muita resistência mas é importante: relacionamentos dentro da empresa.</p><p>Primeiro deixa eu ser claro(a): relacionamentos afetivos entre colegas não são proibidos. A empresa não está na sua vida pessoal. O que ela precisa e tem razão em precisar é ser informada quando isso acontece.</p><p>Por quê? Por causa dos efeitos que um relacionamento pode ter na dinâmica de trabalho. Imagine dois comissários namorando, e um deles é escalado como chefe de cabine responsável pela avaliação do outro. Como fica a imparcialidade? Como ficam os outros membros da equipe que percebem a situação? Como fica o próprio casal numa situação de conflito profissional?</p><p>Não declarar um relacionamento não é só uma questão de transparência é uma infração ao Código de Conduta. E quando descoberta (e costuma ser descoberta), pode resultar em advertência formal para os dois envolvidos, além da anulação de avaliações e processos que possam ter sido afetados.</p><p>O caminho certo é simples: assim que um relacionamento se desenvolver entre colegas, comunique às respectivas gerências. Não precisa ser uma declaração formal constrangedora. É uma conversa. A empresa avalia o contexto e orienta como proceder para evitar conflitos.</p><p>Sobre assédio: esse é outro tema que precisa estar claro. Relacionamento pressupõe reciprocidade e vontade dos dois lados. Qualquer avanço não desejado, pressão por atenção, comentário inadequado sobre a aparência ou corpo de colegas isso é assédio, e você tem o direito e a obrigação de reportar. Tanto se você for a pessoa afetada quanto se você testemunhar.</p>', 10, 'horsky-conduta-67ef1093-1a14-49d2-8d74-af7c86e6c99b'),
  (12, 34, 'Aeroporto: ambiente de trabalho mesmo quando você está de folga', 'Nos aeroportos, você é reconhecido(a) mesmo sem uniforme. Seu comportamento nesses espaços importa mais do que você imagina.', '<img src="/img/aulas/conduta/1779142815938-oljefnugl.jpg" loading="lazy" /><p>Aqui vai uma situação que vai te fazer pensar diferente sobre aeroportos.</p><p>Você está de folga, de calça jeans, sem uniforme, esperando um voo pessoal. Parece que você é só mais um passageiro ali, certo? Não exatamente.</p><p>Aeroportos são ambientes onde passageiros frequentes te reconhecem. Onde colegas de outras empresas te conhecem. Onde supervisores e gestores da sua empresa circulam. Onde câmeras cobrem praticamente todos os espaços. E onde comportamentos inadequados chegam ao conhecimento de quem você menos espera.</p><p>Uma comissária foi reconhecida por um passageiro frequente num aeroporto. Ela estava discutindo em voz alta ao telefone sobre problemas pessoais, com vocabulário bastante colorido. O passageiro a reconheceu como comissária da empresa, filmou e postou. O vídeo chegou ao RH da empresa em menos de um dia.</p><p>Isso não significa que você precisa ser robótico(a) fora do trabalho. Significa que o aeroporto, por ser o ambiente onde sua profissão existe, pede um nível de compostura que outros lugares talvez não peçam.</p><p>É um cuidado que vira hábito com o tempo. E que poupa muita dor de cabeça.</p>', 10, 'horsky-conduta-da53301a-4bf9-463c-b10b-74f562228ad7'),
  (12, 35, 'Passagens de cortesia: entenda o benefício antes de usar', 'O benefício de passagens é um dos mais valorizados na aviação — e um dos mais mal utilizados. Entenda as regras para não perder o emprego por isso.', '<img src="/img/aulas/conduta/1779142844770-gh6otmiqm.jpg" loading="lazy" /><p>Vou falar de um dos benefícios mais incríveis dessa profissão e de como ele já destruiu carreiras de gente que não entendeu as regras.</p><p>O programa de concessão de passagens é um privilégio real. Você e seus dependentes cadastrados (cônjuge, filhos, pais, e em alguns casos o chamado "Amigo Azul" ou equivalente) podem viajar com tarifas especiais ou cortesia, conforme disponibilidade. Para quem ama viajar, esse benefício tem um valor enorme.</p><p>Mas existem regras, e elas são rígidas.</p><p>A passagem é para uso pessoal. Só. Não pode ser cedida para amigos. Não pode ser vendida. Não pode ser usada para viagens a trabalho por nenhum beneficiário. Isso parece óbvio, mas você vai se surpreender com quantas pessoas testaram esses limites.</p><p>Os sistemas das empresas aéreas são sofisticados. Eles identificam padrões de uso que fogem do normal. Emissão frequente para o mesmo destino em datas estratégicas. Passagens utilizadas por pessoas que não constam como dependentes cadastrados. Rotas que claramente não são de uso pessoal.</p><p>Quando isso é identificado e investigado, a consequência é demissão por justa causa. Sem aviso, sem segunda chance. Porque não se trata de um deslize se trata de uso fraudulento de um benefício da empresa.</p><p>Sobre o comportamento dos seus beneficiários: você é responsável por eles a bordo. Se um familiar seu age de forma inadequada num voo de cortesia, as consequências chegam até você. Então quando alguém da sua família for viajar com esse benefício, oriente antes sobre como se portar.</p><p>Use o benefício com alegria ele existe para isso. Mas use dentro das regras. Sempre.</p>', 10, 'horsky-conduta-af77689e-5e1c-43af-88dd-aef9c0248eb4'),
  (12, 41, 'Dados de passageiros: você vê, mas não pode falar', 'Durante o trabalho você acessa informações pessoais de passageiros protegidas por lei. Entenda o que isso significa na prática.', '<img src="/img/aulas/conduta/1779142859972-pipsbdzxo.jpg" loading="lazy" /><p>Deixa eu te mostrar o volume de informação que vai passar pelas suas mãos no dia a dia.</p><p>Você vai saber o nome completo dos passageiros. O destino. O assento. Necessidades especiais — médicas, alimentares, de mobilidade. Em alguns casos, forma de pagamento e informações de contato. Tudo isso está nos sistemas que você acessa para fazer seu trabalho.</p><p>Nenhuma dessas informações pode sair do contexto de trabalho. Ponto.</p><p>E isso inclui situações que parecem inofensivas. Contar pra um amigo que fulano estava no seu voo. Comentar que aquela cantora estava na primeira classe. Tirar foto da lista de passageiros por qualquer motivo. Passar o contato de um passageiro para alguém fora da empresa.</p><p>Existe uma lei que protege esses dados a LGPD e ela tem dentes. Processos judiciais por violação de privacidade existem e acontecem. Mas além da lei, existe o simples respeito: as pessoas que embarcam no seu voo não deram permissão para que suas informações circulem.</p><p>O caso mais sensível, como já mencionei, é o do passageiro famoso. A tentação de comentar é enorme — afinal, é natural querer compartilhar algo interessante. Mas a pergunta que você tem que se fazer é: essa pessoa autorizou que eu divulgue que ela estava naquele voo? A resposta é não. Então não divulgue.</p><p>Cuide dessas informações como se fossem suas. Porque em algum sentido, quando elas passam pelas suas mãos, a responsabilidade sobre elas também é sua.</p>', 10, 'horsky-conduta-37555ca3-8352-4408-9999-80b2e4d1caaf'),
  (12, 42, 'Conversas a bordo: o que não sai da aeronave', 'Situações, decisões e problemas vividos durante o voo são confidenciais. Entenda por que e como lidar com isso.', '<img src="/img/aulas/conduta/1779142876546-fp5h5cd7z.jpg" loading="lazy" /><p>Aqui eu quero falar sobre algo que parece óbvio mas que gera situações complicadas com muito mais frequência do que imagina: as conversas e situações que acontecem a bordo.</p><p>Durante um voo, muita coisa acontece. Decisões do comandante que os passageiros não sabem. Problemas técnicos que foram resolvidos antes de causar qualquer risco mas que assustaram a tripulação. Passageiros difíceis. Conflitos entre tripulantes. Situações inusitadas.</p><p>Tudo isso é confidencial.</p><p>Não porque a empresa tem segredos sujos para esconder. Mas porque tirar uma situação do contexto em que ela aconteceu sem toda a informação, sem o ambiente, sem a resolução cria percepções completamente distorcidas. Um problema técnico resolvido com eficiência pode virar notícia de "aeronave em risco" se virar post nas redes sociais.</p><p>Um comissário, depois de um voo turbulento com um incidente técnico, postou no Twitter algo como "Hoje foi tenso. Quase não contei." com emoji de avião. Ele não disse o número do voo. Mas o horário do post, o destino e a imagem que estava ao fundo permitiram identificar o voo. A empresa rastreou, o comissário foi identificado e iniciou um processo disciplinar que poderia ter sido evitado com um simples silêncio.</p><p>Quando algo acontece a bordo e você precisa reportar e você precisará o canal correto é o Sistema de Gerenciamento de Segurança Operacional da empresa, o relatório de ocorrência, a conversa com o chefe de cabine. Nunca as redes sociais. Nunca uma conversa em voz alta num restaurante. Nunca.</p>', 10, 'horsky-conduta-69d6ea69-fbb8-4377-a1fe-fe61227b1782'),
  (12, 43, 'Fotos e vídeos a bordo: quando pode e quando não pode', 'O interior da aeronave não é cenário pessoal. Entenda as regras sobre o que pode ou não ser fotografado ou filmado.', '<img src="/img/aulas/conduta/1779142902346-h5e4covqk.jpg" loading="lazy" /><p>Esse é um dos temas que mais gera dúvida e também um dos que mais gera problema entre comissários(as) iniciantes. Então vamos clarear de vez.</p><p>O interior da aeronave é patrimônio da empresa. Os equipamentos de segurança, os procedimentos que você executa, a configuração da cabine tudo isso pertence a um universo que tem regras de divulgação. E essas regras existem por razões que vão desde proteção de propriedade intelectual até, em alguns casos, questões de segurança operacional.</p><p>Isso significa que qualquer conteúdo produzido dentro da aeronave foto, vídeo, story, reel precisa de autorização prévia. Não é você que decide o que é inofensivo e o que não é. Essa decisão pertence à área de Comunicação e Marketing da empresa.</p><p>Uma comissária fez um vídeo de "um dia na vida de comissária" que pareceu ótimo para ela: mostrava a cabine, alguns equipamentos, o processo de embarque. Ela achou que estava valorizando a profissão. A empresa entendeu que ela expôs procedimentos de segurança que não devem ser públicos. Processo disciplinar.</p><p>Sobre fotografar passageiros: nunca. Sem exceção. Nem a criança fofa dormindo, nem o passageiro na posição engraçada, nem a celebridade que você reconheceu. Fotografar alguém sem consentimento é violação de privacidade — e se essa foto for parar na internet, vira processo judicial.</p><p>O que você pode fotografar sem problema: destinos que você visitou nas escalas, a vista da janela quando for um conteúdo que não identifique rota ou voo, momentos da sua vida de viajante sem referência à operação. Esse tipo de conteúdo é seguro e bonito.</p>', 10, 'horsky-conduta-81cddb2f-c93a-45ae-9e34-e79d39d7e86c'),
  (12, 44, 'Informações operacionais: por que o sigilo é tão sério', 'Rotas, escalas, procedimentos e qualquer informação do sistema da empresa são confidenciais — e divulgá-los pode ter consequências graves.', '<img src="/img/aulas/conduta/1779142969689-n713xhzvn.jpg" loading="lazy" /><p>Tem uma cena que acontece muito nos aeroportos e que eu quero que você preste atenção: dois tripulantes conversando em voz alta sobre coisas internas da empresa num restaurante cheio, numa sala de espera, num corredor.</p><p>Parece inofensivo. Mas não é.</p><p>Informações sobre rotas que ainda não foram divulgadas ao público, mudanças operacionais, decisões estratégicas da empresa tudo isso tem valor. E quando sai de forma não planejada, pode prejudicar a empresa de várias formas: desde vantagem competitiva para concorrentes até notícias publicadas antes da hora.</p><p>Dois comissários conversavam num restaurante do aeroporto sobre mudanças em rotas internacionais. Um jornalista que estava à mesa ao lado ouviu, confirmou com outras fontes e publicou. A empresa investigou a origem do vazamento. Os dois foram identificados.</p><p>A regra para ambientes públicos é simples: se o assunto é interno, a conversa acontece em ambiente interno. Não num restaurante, não num táxi, não num elevador, não num grupo de WhatsApp onde você não controla quem lê o que.</p><p>E sobre grupos de WhatsApp: eles merecem um cuidado especial. Grupos de colegas de trabalho onde se discutem assuntos da empresa são tecnicamente canais de comunicação da empresa. O que você escreve ali pode ser usado em processos administrativos. E "era um grupo privado" não é argumento o que importa é o conteúdo.</p>', 10, 'horsky-conduta-0ea53a56-584e-4ce0-a7ba-c48b96eabb36'),
  (12, 45, 'O Canal Confidencial: seu aliado, não seu inimigo', 'O canal de denúncias existe para proteger você e seus colegas. Entenda como funciona e quando usá-lo.', '<img src="/img/aulas/conduta/1779143001170-abr3zwpa5.jpg" loading="lazy" /><p>Quero encerrar esse módulo falando de algo que muita gente tem resistência em usar: o canal de denúncias da empresa.</p><p>Existe uma percepção equivocada de que canal de denúncias é ferramenta de perseguição, de que usar é "dedo-duro", de que vai criar inimizades. Entendo de onde vem esse sentimento. Mas quero te mostrar por que ele não faz sentido.</p><p>O canal confidencial existe para que qualquer pessoa colaborador, parceiro, passageiro possa reportar situações que vão contra o Código de Conduta da empresa. Sem medo de retaliação. Sem precisar se identificar se não quiser.</p><p>Situações que justificam o uso: você percebe que um colega está usando o sistema para acessar dados de passageiros sem necessidade operacional. Você é testemunha de assédio. Você vê alguém usando o benefício de passagem de forma fraudulenta. Você recebe uma proposta inadequada de um fornecedor.</p><p>Essas são situações que prejudicam a empresa, os passageiros e potencialmente outros colegas. Reportar não é trair é cumprir o seu papel como profissional.</p><p>A política de não retaliação existe e é levada a sério. Isso significa que a empresa não pode e não deve tomar nenhuma medida contra você pelo fato de ter reportado algo de boa-fé. Se você sentir que houve retaliação, isso em si já é algo que pode ser reportado.</p><p>O canal é anônimo. Você pode fazer o reporte sem se identificar. O processo de investigação é conduzido com sigilo. E ao final, você pode acompanhar o andamento pelo protocolo que recebe.</p><p>Use quando necessário. Ele está lá para isso.</p>', 10, 'horsky-conduta-e0fdab0b-0c67-4746-8f5e-886ed9ae5ebb'),
  (12, 51, 'O que constrói e o que destrói uma carreira na aviação', 'Uma visão honesta dos comportamentos que abrem portas e dos comportamentos que as fecham para sempre.', '<img src="/img/aulas/conduta/1779143018853-2jhb1q8hv.jpg" loading="lazy" /><p>Quero te contar sobre dois comissários que entraram na mesma turma. Mesmas notas no treinamento, mesma competência técnica, mesma base.</p><p>O primeiro foi discreto desde o primeiro dia. Cumpriu horários, não postou nada inadequado, tratou bem todos os colegas independente de hierarquia, reportou o que precisava ser reportado e focou em aprender. Em dois anos, era chefe de cabine.</p><p>O segundo era carismático, muito popular no grupo, sempre animado. Mas postava constantemente sobre o trabalho, tinha opiniões fortes sobre tudo que compartilhava publicamente, se envolveu em algumas situações desnecessárias com colegas. Em dois anos, ainda estava tentando se reposicionar após uma advertência formal que comprometeu sua progressão.</p><p>A diferença não estava na competência. Estava nas escolhas do dia a dia.</p><p>A aviação é um setor pequeno. Menores do que parece. Gestores se conhecem entre empresas. Chefes de cabine conversam. Reputações circulam. Quando você pede transferência, quando troca de empresa, quando busca promoção as pessoas já sabem quem você é antes de te entrevistar.</p><p>Construir uma boa reputação leva anos. Destruí-la pode levar uma noite, um post, uma decisão impulsiva.</p><p>O investimento mais inteligente que você pode fazer agora, no início da carreira, é no tipo de profissional que você quer ser reconhecido(a) como. Todo o resto oportunidades, promoções, reconhecimento vem como consequência disso.</p>', 10, 'horsky-conduta-93532cd7-e251-4114-9638-15008400698a'),
  (12, 52, 'Receber feedback sem levar para o lado pessoal', 'Saber receber avaliação e crítica é uma das habilidades mais valorizadas na aviação — e uma das mais difíceis de desenvolver.', '<img src="/img/aulas/conduta/1779143057553-s4d6ngonu.jpg" loading="lazy" /><p>Tem uma habilidade que separa os profissionais que crescem rápido dos que ficam estagnados na aviação — e não é técnica. É a capacidade de receber feedback.</p><p>Chefe de cabine vai te avaliar depois dos voos. Gestores vão te dar retorno sobre desempenho. Passageiros vão reclamar e elogiar. Auditores vão observar e apontar desvios. Isso faz parte da profissão e é muito mais frequente do que na maioria dos outros empregos.</p><p>O profissional que cresce é o que ouve o feedback, processa, agradece e usa para melhorar. O que não cresce é o que interpreta qualquer crítica como ataque pessoal, que fica na defensiva, que vai comentar nas redes sobre a "avaliação injusta" que recebeu.</p><p>Sobre isso: já falamos sobre não levar assuntos internos para as redes sociais. Mas vale reforçar aqui porque é um erro muito comum. Uma comissária recebeu uma avaliação negativa do chefe de cabine, ficou frustrada e postou nos Stories para "amigos próximos": "Recebi uma avaliação injusta hoje. Chefe de cabine me pegando no detalhe." Um dos amigos próximos era colega de trabalho. Chegou ao RH em 24 horas.</p><p>A frustração é completamente humana e válida. O problema é o canal escolhido para expressá-la.</p><p>O que fazer com um feedback que você acha injusto: peça para conversar com o avaliador e entender melhor os pontos levantados. Se ainda assim achar que foi equivocado, converse com o seu gestor. Existe o caminho formal para contestar. Mas as redes sociais nunca são esse caminho.</p>', 10, 'horsky-conduta-5c296542-5c5b-4647-b7e3-5b0007e62362'),
  (12, 53, 'Diversidade a bordo: respeito que não tem exceção', 'A bordo, você serve pessoas de todas as origens, crenças e orientações. Respeito irrestrito não é opcional — é requisito da profissão.', '<img src="/img/aulas/conduta/1779143080323-jglv75shs.jpg" loading="lazy" /><p>Quando você voa, você serve o mundo. Literalmente.</p><p>Num único voo, você pode ter a bordo pessoas de cinco países diferentes, três religiões diferentes, gerações completamente distintas, pessoas com deficiência, idosos que voam pela primeira vez, crianças que nunca estiveram num avião, viajantes de negócios no limite do estresse e famílias em férias querendo aproveitar cada segundo.</p><p>Cada uma dessas pessoas merece o mesmo padrão de atendimento. Sem exceção. Sem favoritismo. Sem julgamento.</p><p>Isso vai além de não ser grosseiro. Inclui não fazer comentários mesmo que "entre colegas" sobre aparência física de passageiros, sobre hábitos alimentares, sobre a forma como alguém se veste, sobre qualquer característica pessoal. Comentários "inofensivos" entre a equipe de cabine chegam a lugares que você não imagina.</p><p>Um comissário fez uma observação sarcástica para um colega sobre um passageiro durante o embarque. Outro passageiro, que estava próximo, ouviu, gravou e publicou. O comissário foi demitido. O passageiro citado provavelmente nunca soube — mas a vida do comissário mudou completamente por uma frase de cinco segundos.</p><p>Sobre pessoas com deficiência: existem protocolos específicos para atendimento a bordo, e você vai aprendê-los no treinamento técnico. Mas além do protocolo, existe a postura. Tratar com naturalidade, oferecer ajuda sem superproteger, perguntar o que a pessoa precisa ao invés de presumir. Isso não se aprende em manual se desenvolve com empatia.</p><p>Respeito não é difícil. É uma escolha que você faz a cada interação.</p>', 10, 'horsky-conduta-1a5418b5-5f24-46b4-bef9-381033ccd28a'),
  (12, 54, 'Conflito de interesses: quando sua vida pessoal cruza com o trabalho', 'Situações em que sua vida pessoal pode criar conflito com suas responsabilidades profissionais — e o que fazer para evitá-las.', '<img src="/img/aulas/conduta/1779143100138-vuqo8845t.jpg" loading="lazy" /><p>Conflito de interesses é um conceito que parece distante até o momento em que você está no meio de um e aí já é tarde para agir com leveza.</p><p>Deixa eu te dar alguns exemplos concretos para ficar mais claro.</p><p>Você começa a fazer parcerias pagas com uma marca de malas de viagem. Posta fotos com as malas usando o uniforme, com o crachá visível. A marca aparece junto com a imagem da empresa sem que a empresa tenha autorizado. Isso é conflito de interesses e também violação das regras de uso de imagem.</p><p>Você tem um familiar que presta serviço para a empresa como fornecedor. Você está numa posição que pode influenciar essa contratação. Não declarar isso é um problema sério.</p><p>Você trabalha como comissário(a) mas também dá aulas de uma atividade que consome tempo e energia e que eventualmente interfere na sua disponibilidade operacional. Dependendo da situação, pode configurar conflito.</p><p>A lógica é sempre a mesma: quando sua vida pessoal ou seus interesses particulares entram em rota de colisão com os interesses da empresa, você precisa declarar e buscar orientação. Não para ser punido(a) mas para que a situação seja avaliada e, se necessário, gerenciada de forma que proteja tanto você quanto a empresa.</p><p>Esconder é sempre a pior opção. Quando descoberto, o que poderia ter sido resolvido com uma conversa vira um processo disciplinar.</p>', 10, 'horsky-conduta-488fac19-4aeb-4e28-9b4e-9d371cfdd257'),
  (12, 55, 'Seu compromisso começa aqui', 'Aula final. Revisão dos pontos mais importantes e o que significa assinar o Código de Conduta com consciência.', '<img src="/img/aulas/conduta/1779143121387-m8tq1glkv.jpg" loading="lazy" /><p>Chegamos ao fim deste treinamento. E eu quero terminar com algo que vai além de regras.</p><p>Você está entrando numa profissão que pouquíssimas pessoas têm o privilégio de exercer. Você vai ver o sol nascer de um ângulo que a maioria das pessoas nunca vai ver. Vai conhecer cidades, culturas, histórias. Vai estar presente nos momentos mais importantes da vida das pessoas a viagem de férias aguardada o ano inteiro, o reenconto com a família, a viagem de negócios que vai mudar uma carreira.</p><p>Isso é muito. E é bonito.</p><p>Mas tudo isso funciona porque existe uma estrutura de confiança. Passageiros confiam que a tripulação está em condições de voar. A empresa confia que você vai representá-la com integridade. Seus colegas confiam que você vai cumprir o que é seu na operação. Essa confiança é frágil e preciosa.</p><p>O Código de Conduta que você vai assinar não é uma formalidade burocrática. É o mapa desse compromisso. Quando você assina, está dizendo: eu entendo o que essa profissão exige de mim, e eu aceito.</p><p>Então assine com consciência. Leia o documento com atenção. Se tiver dúvida sobre qualquer ponto, pergunte antes de assinar não depois que algo der errado.</p><p>E lembra: a aviação é pequena, a reputação é tudo, a segurança é inegociável e as escolhas que você faz no dia a dia inclusive nas redes sociais, nas escalas, no tratamento com colegas e passageiros constroem ou destroem tudo que você está começando agora.</p><p>Bons voos. Que cada um deles valha a pena.</p>', 10, 'horsky-conduta-358b73ff-d82e-4ffc-bf83-f473d8b4272e')
) v(modulo, ordem, titulo, resumo, conteudo, dur, origem)
join modulos m on m.ordem = v.modulo
on conflict (origem) do update set modulo_id = excluded.modulo_id, ordem = excluded.ordem, titulo = excluded.titulo,
  resumo = excluded.resumo, conteudo = excluded.conteudo, duracao_min = excluded.duracao_min, updated_at = now();

select m.ordem as modulo, m.titulo, count(*) as aulas_importadas
from aulas a join modulos m on m.id = a.modulo_id
where a.origem like 'horsky-hh-%' or a.origem like 'horsky-conduta-%'
group by 1, 2 order by 1;
